sp_page.css:
/* Customize the homepage banner */
.home-banner {
    background-color: #2c3e50;
    color: white;
    padding: 20px;
    text-align: center;
    font-size: 24px;
}

/* Customize the quick actions section */
.quick-actions {
    display: flex;
    justify-content: space-around;
    padding: 10px;
}

.quick-actions button {
    background-color: #2980b9;
    color: white;
    padding: 10px 20px;
    border-radius: 5px;
    font-size: 16px;
    cursor: pointer;
}

.quick-actions button:hover {
    background-color: #1abc9c;
}
